insert into public.dv_settings (id,tagline_en,tagline_sw,hero_title_en,hero_title_sw,hero_subtitle_en,hero_subtitle_sw,phone,whatsapp,email,location_en,location_sw,instagram,facebook,tiktok,youtube,linkedin,founded,hero_video_url,hero_video_mobile_url) values (1,'Turning Moments Into Art','Tunageuza Matukio Kuwa Sanaa','Turning moments into art','Tunageuza matukio kuwa sanaa','Professional photography, cinematic videography and creative visual production for weddings, graduations, events and brands.','Upigaji picha wa kitaalamu, video za kisinema na ubunifu wa kuona kwa harusi, mahafali, matukio na makampuni.','+255 756 506 908','255756506908','dolfvisuals@gmail.com','Dar es Salaam, Tanzania','Dar es Salaam, Tanzania',null,null,null,null,null,'2025-10-11',null,null)
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('wedding','wedding-photography','/portfolio/bridal-staircase.webp',1,true,'Wedding Photography & Videography','Picha na Video za Harusi','Ceremonies, receptions, couple portraits and every moment in between.','Sherehe, mapokezi, picha za maharusi na kila tukio katikati yake.','Capturing wedding ceremonies, receptions, couples'' portraits and memorable wedding moments — documented with a cinematic eye and delivered as a story you''ll relive for a lifetime.','Tunanasa sherehe za harusi, mapokezi, picha za maharusi na matukio yote ya kukumbukwa — kwa jicho la kisinema, na kukukabidhi simulizi utakayoikumbuka maisha yote.');
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('photography','commercial','/portfolio/studio-portrait-chair-1.webp',2,true,'Photography','Upigaji Picha','Professional photography for individuals, brands and organizations.','Picha za kitaalamu kwa watu binafsi, makampuni na taasisi.','Professional photography services for individuals, brands and organizations — studio and on-location, with controlled lighting, creative framing and consistent editing.','Huduma za upigaji picha za kitaalamu kwa watu binafsi, makampuni na taasisi — studio au eneo la tukio, kwa mwanga uliodhibitiwa, mpangilio wa kibunifu na uhariri thabiti.');
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('videography','promotional-videos','/portfolio/tia-marathon-duo.webp',3,true,'Videography','Upigaji Video','Event films and cinematic visual storytelling.','Filamu za matukio na usimulizi wa kisinema.','High-quality video production, event films and cinematic visual storytelling — smooth camera movement, professional audio and consistent colour grading.','Utengenezaji wa video za ubora wa juu, filamu za matukio na usimulizi wa kisinema — kamera tulivu, sauti ya kitaalamu na rangi zinazolingana.');
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('graduation','graduation','/portfolio/lifestyle-sunset-joy.webp',4,true,'Graduation Photography','Picha za Mahafali','Portraits, group shots and graduation celebrations.','Picha binafsi, za makundi na sherehe za mahafali.','Professional graduation portraits, individual sessions, group photography and graduation celebrations.','Picha za mahafali za kitaalamu, sessions binafsi, picha za makundi na sherehe za mahafali.');
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('birthday-events','events','/portfolio/tia-marathon-friends.webp',5,true,'Birthday & Event Coverage','Birthday na Matukio','Birthdays, private celebrations, parties and special occasions.','Birthday, sherehe binafsi, pati na matukio maalum.','Photography and videography for birthdays, private celebrations, parties and special occasions.','Picha na video kwa birthday, sherehe binafsi, pati na matukio maalum.');
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('corporate','corporate-photography','/portfolio/corporate-portrait-suit.webp',6,true,'Corporate Photography & Videography','Picha na Video za Kikampuni','Headshots, conferences, corporate events and business branding.','Picha za wafanyakazi, mikutano, matukio ya kikampuni na branding.','Professional visual content for companies, organizations, conferences, corporate events and business branding — including executive headshots and team portraits.','Maudhui ya kitaalamu kwa makampuni, taasisi, mikutano, matukio ya kikampuni na branding ya biashara — pamoja na picha za viongozi na timu.');
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('product','product',null,7,true,'Product Photography','Picha za Bidhaa','Clean, high-quality product images for e-commerce and ads.','Picha safi za bidhaa kwa maduka ya mtandaoni na matangazo.','High-quality product images for businesses, e-commerce platforms, advertising and marketing campaigns.','Picha za bidhaa za ubora wa juu kwa biashara, maduka ya mtandaoni, matangazo na kampeni za masoko.');
insert into public.dv_services (slug,portfolio_category,cover_url,sort,published,title_en,title_sw,summary_en,summary_sw,description_en,description_sw) values ('commercial','commercial','/portfolio/studio-portrait-golden.webp',8,true,'Commercial & Promotional Content','Maudhui ya Matangazo','Promotional videos, ad content and brand campaigns.','Video za matangazo, maudhui ya matangazo na kampeni za brand.','Creative promotional videos, advertising content, brand campaigns and business storytelling.','Video za matangazo za kibunifu, maudhui ya matangazo, kampeni za brand na usimulizi wa biashara.');
